diff --git a/src/bff/app-model/translations/fetch-translations.ts b/src/bff/app-model/translations/fetch-translations.ts
new file mode 100644
index 0000000..8ee8a32
--- /dev/null
+++ b/src/bff/app-model/translations/fetch-translations.ts
@@ -0,0 +1,37 @@
+import type {Client} from '@urql/core';
+import {
+  type GetFeatureAppTranslationsByPathQuery,
+  type GetFeatureAppTranslationsByPathQueryVariables,
+  getFeatureAppTranslationsByPath,
+} from '../../../graphql';
+
+interface FetchTranslationsOptions {
+  readonly client: Client;
+  readonly options: {
+    readonly path: string;
+    readonly url: string;
+  };
+}
+
+export const fetchTranslations = async ({
+  client,
+  options,
+}: FetchTranslationsOptions) => {
+  const {data} = await client
+    .query<
+      GetFeatureAppTranslationsByPathQuery,
+      GetFeatureAppTranslationsByPathQueryVariables
+    >(getFeatureAppTranslationsByPath, {
+      translationsPath: options.path,
+    })
+    .toPromise();
+
+  if (!data) {
+    console.debug(
+      `GetFeatureAppTranslationsByPathQuery data is missing when fetching client url: ${options.url}`,
+    );
+    return undefined;
+  }
+
+  return data;
+};

