+import type {Client} from '@urql/core';
+import type {GraphQLSchema} from 'graphql';
+import {GetCommonFootnotesFragment} from '../graphql';
+import type {
+  GetCommonFootnotesFragmentQuery,
+  GetCommonFootnotesFragmentQueryVariables,
+} from '../graphql';
+
+export interface FetchBadgeFootnotesContentFragmentOptions {
+  readonly client: Client;
+  readonly marketId: string;
+  readonly language: string;
+  readonly schema: GraphQLSchema;
+}
+
+const featureAppContentsDirname = `/content/dam/smart/feature-apps/content`;
+
+export async function fetchBadgeFootnotesContentFragment(
+  options: FetchBadgeFootnotesContentFragmentOptions,
+): Promise<GetCommonFootnotesFragmentQuery> {
+  const {client, marketId, language, schema} = options;
+
+  const aemCommonFootnotesPath = path.posix.join(
+    featureAppContentsDirname,
+    `common`,
+    marketId,
+    language,
+    `common-footnotes`,
+  );
+
+  const {data} = await client
+    .query<
+      GetCommonFootnotesFragmentQuery,
+      GetCommonFootnotesFragmentQueryVariables
+    >(
+      sanitizeAemQuery({
+        schema,
+        query: GetCommonFootnotesFragment,
+        logger: console.info.bind(console),
+      }),
+      {path: aemCommonFootnotesPath},
+    )
+    .toPromise();
+
+  if (!data) {
+    throw new Error(`GetCommonFootnotesFragmentQuery data is missing`);
+  }
+
+  return data;
+}

