+import type {Highlight} from '../../../bff/get-garage/create-garage-model';
+
+// Mock getHexFromColorCode function
+const mockGetHexFromColorCode = jest.fn(
+  (code: string, _fallback: string = ``) => {
+    return code && code !== `` ? `#FFFFFF` : ``;
+  },
+);
+
+jest.mock(`@smart/web-components`, () => ({
+  getHexFromColorCode: mockGetHexFromColorCode,
+  ColorTile: () => null,
+  Text: () => null,
+}));
+
+// Extract the getColorText function logic for testing
+// This replicates the logic from index.tsx
+const getColorText = (item: Highlight): string => {
+  // Simulate getHexFromColorCode behavior
+  const hexValue = mockGetHexFromColorCode(item.roofColorCode || ``, ``);
+  if (hexValue !== ``) {
+    return `${item.text} / ${item.roofDescription || ``}`;
+  }
+  return item.text;
+};
+
+describe(`getColorText function`, () => {
+  beforeEach(() => {
+    jest.clearAllMocks();
+  });
+
+  it(`should return text with roof description when roofColorCode exists`, () => {
+    mockGetHexFromColorCode.mockReturnValue(`#FFFFFF`); // Non-empty return
+
+    const item: Highlight = {
+      id: `exteriorColor`,
+      text: `Digital White Metallic`,
+      roofColorCode: `ROOF-001`,
+      roofDescription: `Black Roof`,
+      colorCode: `WHITE-001`,
+    };
+
+    const result = getColorText(item);
+    expect(result).toBe(`Digital White Metallic / Black Roof`);
+    expect(mockGetHexFromColorCode).toHaveBeenCalledWith(`ROOF-001`, ``);
+  });
+
+  it(`should return only text when roofColorCode does not exist`, () => {
+    mockGetHexFromColorCode.mockReturnValue(``); // Empty return
+
+    const item: Highlight = {
+      id: `exteriorColor`,
+      text: `Digital White Metallic`,
+      roofColorCode: undefined,
+      colorCode: `WHITE-001`,
+    };
+
+    const result = getColorText(item);
+    expect(result).toBe(`Digital White Metallic`);
+    expect(mockGetHexFromColorCode).toHaveBeenCalledWith(``, ``);
+  });
+
+  it(`should return only text when roofColorCode is empty string`, () => {
+    mockGetHexFromColorCode.mockReturnValue(``); // Empty return
+
+    const item: Highlight = {
+      id: `exteriorColor`,
+      text: `Cosmic Blue`,
+      roofColorCode: ``,
+      colorCode: `BLUE-001`,
+    };
+
+    const result = getColorText(item);
+    expect(result).toBe(`Cosmic Blue`);
+    expect(mockGetHexFromColorCode).toHaveBeenCalledWith(``, ``);
+  });
+});

diff --git a/src/feature-app/components/highlightlist/index.tsx b/src/feature-app/components/highlightlist/index.tsx
