--- /dev/null
+++ b/src/feature-app/components/highlightlist/index.tsx
@@ -0,0 +1,93 @@
+import {Text} from '@smart/react-components';
+import {ColorTile, getHexFromColorCode} from '@smart/web-components';
+import React from 'react';
+import type {DisclaimerRefs} from '../../../bff/app-model/create-app-model';
+import type {Highlight as HighlightType} from '../../../bff/get-garage/create-garage-model';
+import {Highlight} from '../highlight';
+import styles from './index.module.scss';
+
+interface HighlightListProps {
+  id: string;
+  exteriorLabel?: string;
+  interiorLabel?: string;
+  listItems: HighlightType[];
+  disclaimerRefs?: DisclaimerRefs;
+}
+
+const isColor = (colorId: string): boolean =>
+  colorId === `exteriorColor` || colorId === `interiorColor`;
+
+const getColorText = (item: HighlightType): string => {
+  const hexValue = getHexFromColorCode(item.colorCode!);
+  const roofHexValue = getHexFromColorCode(item.roofColorCode || ``, ``);
+
+  if (hexValue !== roofHexValue && roofHexValue !== ``) {
+    return `${item.text} / ${item.roofDescription || ``}`;
+  }
+  return item.text;
+};
+
+const getDisclaimerRef = (
+  highlightId: string,
+  disclaimerRefs?: DisclaimerRefs,
+): string | undefined => {
+  if (!disclaimerRefs) return undefined;
+
+  // Map highlight IDs to disclaimer reference keys
+  const mapping: Record<string, keyof DisclaimerRefs> = {
+    [`CONSUMPTION_range_wltp_combined`]: `rangeWltpCombined`,
+    [`CONSUMPTION_dcchargingtime`]: `dcChargingTime`,
+    [`POWER.acceleration`]: `powerAcceleration`,
+  };
+
+  const key = mapping[highlightId];
+  return key ? disclaimerRefs[key] : undefined;
+};
+
+export const HighlightList: React.FC<HighlightListProps> = ({
+  id,
+  listItems,
+  exteriorLabel,
+  interiorLabel,
+  disclaimerRefs,
+}) => {
+  const notColorItems = listItems.filter((item) => !isColor(item.id));
+  const colorItems = listItems.filter((item) => isColor(item.id));
+
+  return (
+    <div>
+      <ul className={styles.productCardHighlights}>
+        {notColorItems.map((item) => (
+          <li key={`product-card-${id}-highlight-${item.id}`}>
+            <Highlight
+              text={item.text}
+              disclaimerRef={getDisclaimerRef(item.id, disclaimerRefs)}
+            />
+          </li>
+        ))}
+      </ul>
+      <ul className={styles.productTilesContainer}>
+        {colorItems.map((item) => (
+          <li
+            key={`product-card-${id}-highlight-${item.id}`}
+            className={styles.colorItem}
+          >
+            {item.colorCode && (
+              <ColorTile
+                id={item.id}
+                primaryColor={getHexFromColorCode(item.colorCode!)}
+                secondaryColor={getHexFromColorCode(item.roofColorCode, ``)}
+                titleText={item.text}
+              />
+            )}
+            <Text variant="p-100" as="span">
+              {item.id === `exteriorColor`
+                ? `${exteriorLabel?.replace(`:`, ``)}: ${getColorText(item)}`
+                : `${interiorLabel?.replace(`:`, ``)}: ${item.text}`}
+            </Text>
+          </li>
+        ))}
+      </ul>
+    </div>
+  );
+};

