+import {Dialog, Flex} from '@smart/react-components';
+import {IconButton, LegalDisclaimer} from '@smart/web-components';
+import React, {useRef, useState} from 'react';
+import styles from './index.module.scss';
+
+export type LegalDisclaimerItem = {
+  legalText: string;
+  image?: {
+    imageAltText: string;
+    imageUrl: string;
+  };
+  className?: string;
+};
+
+export type LegalDisclaimerWithModalProps = {
+  /**
+   * Array of legal disclaimer items to display.
+   * Each item should contain legalText and optionally an image.
+   */
+  disclaimers: LegalDisclaimerItem[];
+  /**
+   * Whether the energy label modal is enabled.
+   * When enabled, clicking on the disclaimer image will open a modal with a larger image.
+   */
+  isEnergyLabelModalEnabled?: boolean;
+  /**
+   * URL for the large energy label image to display in the modal.
+   * This should be a high-resolution version of the energy label image.
+   */
+  largeEnergyLabelImageUrl?: string;
+  /**
+   * Optional CSS class name for the modal image.
+   */
+  imageClassName?: string;
+};
+
+export const LegalDisclaimerWithModal: React.FC<
+  LegalDisclaimerWithModalProps
+> = ({
+  disclaimers,
+  isEnergyLabelModalEnabled = false,
+  largeEnergyLabelImageUrl,
+  imageClassName,
+}) => {
+  const [modalOpen, setModalOpen] = useState(false);
+  const pictureRef = useRef<HTMLDivElement | null>(null);
+
+  const handleDisclaimersClick = (
+    event: React.MouseEvent<HTMLDivElement>,
+  ): void => {
+    if (
+      pictureRef.current &&
+      pictureRef.current.contains(event.target as Node)
+    ) {
+      setModalOpen(true);
+    }
+  };
+
