+export const DiscountPricing = ({
+  buyPrice,
+  cashBuyTaxLabel,
+  basePrice,
+  discount,
+}: DiscountPricingProps): JSX.Element => {
+  const appModel = useAppModelContext();
+  const {t} = useTranslations(appModel.translations ?? {});
+  const parts = t(`discount.listPriceDiscription`).split(`{{price}}`);
+  const MAX_BADGE_LENGTH = 25;
+
+  // Determine discount tag value based on usePercentageDiscount flag
+  const usePercentageDiscount = t(`discount.usePercentageDiscount`) === `true`;
+  const discountTagValue = usePercentageDiscount
+    ? discount?.totalDiscountPercentage !== undefined
+      ? `${discount.totalDiscountPercentage}%`
+      : ``
+    : (discount?.formattedValue ?? ``);
+
+  // Generate badge text and truncate if necessary
+  const getBadgeText = (): string => {
+    const badgeText = t(`discount.tag`).replace(
+      `{{discountTagPrice}}`,
+      discountTagValue,
+    );
+    return badgeText.length > MAX_BADGE_LENGTH
+      ? `${badgeText.slice(0, MAX_BADGE_LENGTH - 1)}…`
+      : badgeText;
+  };
+
+  return (
+    <div className={styles[`${baseClass}__label-wrapper`]}>
+      <Text className={styles[`${baseClass}__label`]} variant={`p-100`}>
+        {t(`discount.priceLabel`)}
+        <sup>{t(`discount.priceLabelSuperscript`)}</sup>
+      </Text>
+      <div className={styles[`${baseClass}__price-wrapper`]}>
