+import type {StackContext} from 'sst/constructs';
+import {Api, use} from 'sst/constructs';
+import {AppConfig} from './AppConfig';
+
+export function BffApi({stack}: StackContext) {
+  const {hostedZone, featureAppName, target} = use(AppConfig);
+  const baseUrl = `/__app__/${featureAppName}/${target}`;
+  const privateBaseUrl = baseUrl.replace(`/__app__/`, `/__app-private__/`);
+  const api = new Api(stack, `api`, {
+    customDomain: {
+      hostedZone,
+      domainName: [`stage`, `dev`, `prod`].includes(stack.stage)
+        ? `bff.${hostedZone}`
+        : `bff.${stack.stage}.${hostedZone}`,
+    },
+    routes: {
+      [`GET ${baseUrl}/bff/app-model`]: {
+        function: {
+          handler: `src/bff/app-model/index.handler`,
+          functionName: `BffAppModelFunction-${stack.stage}`,
+          memorySize: 1769,
+        },
+      },
+      [`GET ${privateBaseUrl}/bff/get-garage`]: {
+        function: {
+          handler: `src/bff/get-garage/index.handler`,
+          functionName: `BffGetGarageFunction-${stack.stage}`,
+          memorySize: 1769,
+        },
+      },
+      [`POST ${privateBaseUrl}/bff/post-garage`]: {
+        function: {
+          handler: `src/bff/post-garage/index.handler`,
+          functionName: `BffPostGarageFunction-${stack.stage}`,
+          memorySize: 1769,
+        },
+      },
+      [`DELETE ${privateBaseUrl}/bff/delete-garage`]: {
+        function: {
+          handler: `src/bff/delete-garage/index.handler`,
+          functionName: `BffDeleteGarageFunction-${stack.stage}`,
+          memorySize: 1769,
+        },
+      },
+    },
+  });
+  stack.addOutputs({
+    apiUrl: api.customDomainUrl ?? api.url,
+  });
+  return api;
+}

