+import path from 'path';
+import CssMinimizerPlugin from 'css-minimizer-webpack-plugin';
+import MiniCssExtractPlugin from 'mini-css-extract-plugin';
+import type {Configuration} from 'webpack';
+import {DefinePlugin} from 'webpack';
+
+interface GetCommonConfigOptions {
+  readonly mode: Configuration['mode'];
+  readonly baseUrl: string;
+  readonly stage: string;
+  readonly target: string;
+  readonly featureAppName: string;
+}
+
+export const buildPath = (...pathname: string[]) =>
+  path.join(process.cwd(), ...pathname);
+
+export const getCommonConfig = (
+  options: GetCommonConfigOptions,
+): Configuration => {
+  const isProd = options.mode === `production`;
+  return {
+    infrastructureLogging: {
+      level: `error`,
+    },
+    resolve: {
+      extensions: [`.js`, `.json`, `.ts`, `.tsx`],
+      fallback: {
+        path: false,
+        fs: false,
+      },
+    },
+    plugins: [
+      new DefinePlugin({
+        'process.env.BASE_URL': JSON.stringify(options.baseUrl),
+        'process.env.NODE_ENV': JSON.stringify(options.mode),
+        'process.env.TARGET': JSON.stringify(options.target),
+        'process.env.STAGE': JSON.stringify(options.stage),
+      }),
+      new MiniCssExtractPlugin(),
+    ],
+    devtool: isProd ? false : `source-map`,
+    optimization: {
+      minimize: isProd,
+      minimizer: [`...`, new CssMinimizerPlugin()],
+    },
+    module: {
+      rules: [
+        {
+          test: /\.m?js$/,
+          resolve: {
+            fullySpecified: false,
+          },
+        },
+        {
+          test: /\.js$/,
+          loader: `source-map-loader`,
+          enforce: `pre`,
+        },
+        {
+          test: /\.tsx?$/,
+          use: {loader: `swc-loader`},
+          exclude: [/node_modules/],
+        },
+        {
+          test: /\.svg/,
+          type: `asset/resource`,
+        },
+        {
+          test: /\.s?css$/,
+          use: [
+            MiniCssExtractPlugin.loader,
+            {
+              loader: `css-loader`,
+              options: {
+                modules: {
+                  localIdentName: isProd
+                    ? `[hash:base64:7]`
+                    : `[local]__[hash:base64:5]`,
+                  localIdentHashSalt: `${options.featureAppName}/${options.stage}`,
+                  auto: true,
+                },
+              },
+            },
+            {
+              loader: `postcss-loader`,
+              options: {
+                postcssOptions: {plugins: [`autoprefixer`]},
+              },
+            },
+            {
+              loader: `sass-loader`,
+              options: {
+                additionalData: `$baseUrl: '${options.baseUrl}';`,
+              },
+            },
+          ],
+        },
+      ],
+    },
+  };
+};

